{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "The closest analogue, a benzimidazole-piperidine with B/Pb 2.7, shows the core scaffold can be CNS-permeable, but it lacks the query's ionized carboxylic acid and zwitterionic character, so this positive result does not transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "A brain-penetrant benzimidazole reached 13 µM in rat brain after IP dosing, but it is a lipophilic amide without the acid group; its exposure does not overcome the query's passive-permeability liability from full ionization and very low logD.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Secondary amide analogues with the piperidine-benzimidazole scaffold had brain Cmax values consistent with free passage, but they are non-zwitterionic lipophilic bases; the query's carboxylic acid introduces full ionization and a much lower logD.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "SA4503 shows high receptor-specific brain uptake in rats, but it is a lipophilic basic amine with no acid; this supports CNS penetration of bases, not the query's zwitterionic acid-containing structure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "Benperidol PET imaging shows rapid brain localization, but it is a lipophilic basic drug; its permeability does not apply to a fully ionized zwitterion with a free carboxylic acid and high rotatable-bond count.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large zwitterionic benzimidazole-piperidine with a free carboxylic acid and basic amine, fully ionized at pH 7.4 and very low estimated logD. The experimental analogues are lipophilic CNS-permeable bases lacking the acid/zwitterion, and their Morgan similarities are low (max ~0.39), so their positive brain-penetration results do not transfer. Passive BBB access is expected to be inadequate, and no evidence supports active uptake overcoming the charge and polarity burden.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or uptake data for the exact query or a close zwitterionic analogue.",
    "Efflux-transporter substrate status of the query is unknown.",
    "Estimated logD and pKa values may have errors, and active transport cannot be fully excluded."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

